	inline float Height(const std::int16_t* cells, int x0, int z0, int columns, int rows, float x, float z, float& out)
	{
		const int ix = static_cast<int>((x - x0) / Step + (x >= x0 ? 0.5f : -0.5f));
		const int iz = static_cast<int>((z - z0) / Step + (z >= z0 ? 0.5f : -0.5f));
		if (ix < 0 || iz < 0 || ix >= columns || iz >= rows || cells[iz * columns + ix] == None)
		{
			return 0.0f;
		}
		out = static_cast<float>(cells[iz * columns + ix]);
		return 1.0f;
	}
